SELECT cd.cd_gender, cd.cd_education_status, cd.cd_marital_status, cd.cd_credit_rating, SUM(ws.ws_net_paid) AS total_sales, SUM(ws.ws_quantity) AS total_quantity_sold, SUM(COALESCE(wr.wr_return_quantity, 0)) AS total_quantity_returned, SUM(COALESCE(wr.wr_net_loss, 0)) AS total_return_loss, SUM(ws.ws_net_profit) - SUM(COALESCE(wr.wr_net_loss, 0)) AS net_profit_after_returns, CASE WHEN SUM(ws.ws_quantity) > 0 THEN SUM(COALESCE(wr.wr_return_quantity, 0)) / CAST(SUM(ws.ws_quantity) AS double) ELSE 0 END AS return_rate, CASE WHEN SUM(ws.ws_quantity) > 0 THEN SUM(ws.ws_ext_discount_amt) / CAST(SUM(ws.ws_quantity) AS double) ELSE 0 END AS avg_discount_per_item, RANK() OVER (ORDER BY (SUM(ws.ws_net_profit) - SUM(COALESCE(wr.wr_net_loss, 0))) DESC) AS profit_rank FROM web_sales ws JOIN customer_demographics cd ON ws.ws_bill_cdemo_sk = cd.cd_demo_sk LEFT JOIN web_returns wr ON ws.ws_order_number = wr.wr_order_number AND ws.ws_item_sk = wr.wr_item_sk WHERE ws.ws_sold_date_sk BETWEEN 2450000 AND 2451500 AND cd.cd_credit_rating = 'Excellent' GROUP BY cd.cd_gender, cd.cd_education_status, cd.cd_marital_status, cd.cd_credit_rating HAVING SUM(ws.ws_net_paid) > 10000 ORDER BY profit_rank LIMIT 10
